import{_ as i,a0 as p,w as a,s as m,ao as n,I as o,x as e,a1 as l,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux有問必答：如何通過命令列創建和設置一個MySQL用户 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何通過命令列創建和設置一個MySQL用户 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何通過命令列創建和設置一個MySQL用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何通過命令列創建和設置一個MySQL用户 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150122 Linux FAQs with Answers--How to create and configure a MySQL user from the command line","title":"Linux有問必答：如何通過命令列創建和設置一個MySQL用户","tag":"201503","desc":""},"relativePath":"201503/20150122 Linux FAQs with Answers--How to create and configure a MySQL user from the command line.md","filePath":"[post].md"}'),u={name:"201503/20150122 Linux FAQs with Answers--How to create and configure a MySQL user from the command line.md"};function d(g,t,y,S,L,T){const r=p("Link");return a(),m("div",null,[t[19]||(t[19]=n(`<h1 id="linux有問必答-如何通過命令列創建和設置一個mysql用户" tabindex="-1">Linux有問必答：如何通過命令列創建和設置一個MySQL用户 <a class="header-anchor" href="#linux有問必答-如何通過命令列創建和設置一個mysql用户" aria-label="Permalink to “Linux有問必答：如何通過命令列創建和設置一個MySQL用户”">​</a></h1><blockquote><p><strong>問題</strong>：我想要在MySQL服務器上創建一個新的用户帳號，並且賦予他適當的權限和資源限制。如何通過命令列的方式來創建並且設置一個MySQL用户呢？</p></blockquote><p>要訪問一個MySQL服務器，你需要使用一個用户帳號登錄其中方可進行。每個MySQL用户帳號都有許多與之相關連的屬性，例如用户名、密碼以及權限和資源限制。&quot;權限&quot;定義了特定用户能夠在MySQL服務器中做什麼，而&quot;資源限制&quot;為用户設置了一系列服務器資源的使用許可。創建或更新一個用户涉及到了對用户帳號所有屬性的管理。</p><p>下面展示瞭如何在Linux中創建和設置一個MySQL用户。</p><p>首先以root身份登錄到MySQL服務器中。</p><pre><code>$ mysql -u root -p
</code></pre><p>當驗證提示出現的時候，輸入MySQL的root帳號的密碼。</p><p><img src="https://farm8.staticflickr.com/7482/16024190060_fff53d8840_b.jpg" alt=""></p><h3 id="創建一個mysql用户" tabindex="-1">創建一個MySQL用户 <a class="header-anchor" href="#創建一個mysql用户" aria-label="Permalink to “創建一個MySQL用户”">​</a></h3><p>使用如下命令創建一個用户名和密碼分別為&quot;myuser&quot;和&quot;mypassword&quot;的用户。</p><pre><code>mysql&gt; CREATE USER &#39;myuser&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;mypassword&#39;;
</code></pre><p>一旦用户被創建後，包括加密的密碼、權限和資源限制在內的所有帳號細節都會被存儲在一個名為<strong>user</strong>的表中，這個表則存在於<strong>mysql</strong>這個特殊的資料庫裏。</p><p>運行下列命令，驗證帳號是否創建成功</p><pre><code>mysql&gt; SELECT host, user, password FROM mysql.user WHERE user=&#39;myuser&#39;;
</code></pre><h3 id="賦予mysql用户權限" tabindex="-1">賦予MySQL用户權限 <a class="header-anchor" href="#賦予mysql用户權限" aria-label="Permalink to “賦予MySQL用户權限”">​</a></h3><p>一個新建的MySQL用户沒有任何訪問權限，這就意味着你不能在MySQL資料庫中進行任何操作。你得賦予用户必要的權限。以下是一些可用的權限：</p><ul><li><strong>ALL</strong>: 所有可用的權限</li><li><strong>CREATE</strong>: 創建庫、表和索引</li><li><strong>LOCK_TABLES</strong>: 鎖定表</li><li><strong>ALTER</strong>: 修改表</li><li><strong>DELETE</strong>: 刪除表</li><li><strong>INSERT</strong>: 插入表或列</li><li><strong>SELECT</strong>: 檢索表或列的數據</li><li><strong>CREATE_VIEW</strong>: 創建視圖</li><li><strong>SHOW_DATABASES</strong>: 列出資料庫</li><li><strong>DROP</strong>: 刪除庫、表和視圖</li></ul><p>運行以下命令賦予&quot;myuser&quot;用户特定權限。</p><pre><code>mysql&gt; GRANT &lt;privileges&gt; ON &lt;database&gt;.&lt;table&gt; TO &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p>以上命令中，<code>&lt;privileges&gt;</code> 代表着用逗號分隔的權限列表。如果你想要將權限賦予任意資料庫（或表），那麼使用星號（*）來代替資料庫（或表）的名字。</p><p>例如，為所有資料庫/表賦予 CREATE 和 INSERT 權限：</p><pre><code>mysql&gt; GRANT CREATE, INSERT ON *.* TO &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p>驗證給用户賦予的全權限：</p><pre><code>mysql&gt; SHOW GRANTS FOR &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p><img src="https://farm8.staticflickr.com/7556/16209665261_923282bddd_c.jpg" alt=""></p><p>將全部的權限賦予所有資料庫/表：</p><pre><code>mysql&gt; GRANT ALL ON *.* TO &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><p>你也可以將用户現有的權限刪除。使用以下命令廢除&quot;myuser&quot;帳號的現有權限：</p><pre><code>mysql&gt; REVOKE &lt;privileges&gt; ON &lt;database&gt;.&lt;table&gt; FROM &#39;myuser&#39;@&#39;localhost&#39;;
</code></pre><h3 id="為用户添加資源限制" tabindex="-1">為用户添加資源限制 <a class="header-anchor" href="#為用户添加資源限制" aria-label="Permalink to “為用户添加資源限制”">​</a></h3><p>在MySQL中，你可以為單獨的用户設置MySQL的資源使用限制。可用的資源限制如下：</p>`,31)),o("ul",null,[t[4]||(t[4]=o("li",null,[o("strong",null,"MAX_QUERIES_PER_HOUR"),e(": 允許的每小時最大請求數量")],-1)),t[5]||(t[5]=o("li",null,[o("strong",null,"MAX_UPDATES_PER_HOUR"),e(": 允許的每小時最大更新數量")],-1)),o("li",null,[t[1]||(t[1]=o("strong",null,"MAX_CONNECTIONS_PER_HOUR",-1)),t[2]||(t[2]=e(": 允許的每小時最大連接（譯者注：",-1)),l(r,{href:"http://dev.mysql.com/doc/refman/5.0/en/user-resources.html"},{default:s(()=>[...t[0]||(t[0]=[e("其與 MySQL全局變量： max_user_connections 共同決定用户到資料庫的同時連接數量",-1)])]),_:1}),t[3]||(t[3]=e("）數量",-1))]),t[6]||(t[6]=o("li",null,[o("strong",null,"MAX_USER_CONNECTIONS"),e(": 對服務器的同時連接量")],-1))]),t[20]||(t[20]=n(`<p>使用以下命令為&quot;myuser&quot;帳號增加一個資源限制：</p><pre><code>mysql&gt; GRANT USAGE ON &lt;database&gt;.&lt;table&gt; TO &#39;myuser&#39;@&#39;localhost&#39; WITH &lt;resource-limits&gt;;
</code></pre><p>在 <code>&lt;resource-limits&gt;</code> 中你可以指定多個使用空格分隔開的資源限制。</p><p>例如，增加 MAX_QUERIES_PER_HOUR 和 MAX_CONNECTIONS_PER_HOUR 資源限制：</p><pre><code>mysql&gt; GRANT USAGE ON *.* TO &#39;myuser&#39;@&#39;localhost&#39; WITH MAX_QUERIES_PER_HOUR 30 MAX_CONNECTIONS_PER_HOUR 6;
</code></pre><p>驗證用户的資源限制：</p><pre><code>mysql&gt; SHOW GRANTS FOR &#39;myuser&#39;@&#39;localhost;
</code></pre><p><img src="https://farm8.staticflickr.com/7537/16025443759_5cb4177bc6_c.jpg" alt=""></p><p>創建和設置一個MySQL用户最後的一個重要步驟：</p><pre><code>mysql&gt; FLUSH PRIVILEGES;
</code></pre><p>如此一來更改便生效了。現在MySQL用户帳號就可以使用了。</p><hr>`,12)),o("p",null,[t[8]||(t[8]=e("via: ",-1)),l(r,{href:"http://ask.xmodulo.com/create-configure-mysql-user-command-line.html"},{default:s(()=>[...t[7]||(t[7]=[e("http://ask.xmodulo.com/create-configure-mysql-user-command-line.html",-1)])]),_:1})]),o("p",null,[t[11]||(t[11]=e("譯者：",-1)),l(r,{href:"http://weibo.com/370321376"},{default:s(()=>[...t[9]||(t[9]=[e("Ping",-1)])]),_:1}),t[12]||(t[12]=o("br",null,null,-1)),t[13]||(t[13]=e(" 校對：",-1)),l(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創翻譯，",-1)),l(r,{href:"http://linux.cn/"},{default:s(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const A=i(u,[["render",d]]);export{f as __pageData,A as default};
